fn leak_loop()
    let acc = []
    let i = 0
    while i < 100
        let temp = [i]          // fresh, RC=1, stored to slot 'temp'
        acc = acc + temp         // list_concat -> new list, stored to 'acc'
        i = i + 1
    return acc
// S3 fires rc_drop_reassign on 'temp' each iteration (old temp dec'd). GOOD.
// S4 fires rc_dec on 'temp' at return. But after the LAST iteration,
// S3 already dropped temp[99] (overwritten by... wait, the LAST iteration
// is the last store, S3 fires on the PENULTIMATE's old value).
// Actually: S3 fires BEFORE the new store (load old, drop old, store new).
// At return, temp holds the LAST iteration's list. S3 never dropped IT.
// S4 drops it. That is ONE dec. RC was 1 (fresh). Goes to 0. Freed.
// BUT: temp[99]'s elements were appended into acc via list_concat,
// which rc_inc'd them. So the recursive dec on temp[99]'s elements
// brings them from 2 to 1. acc still holds them. SAFE.
// FALSE ALARM on this specific case. However...

fn process(items)
    let current = items[0]    // index_get -> borrowed -> rc_inc at store -> RC=2
    for item in items
        if pred(item)
            current = item    // item is from for-in index_get -> borrowed
                              // rc_inc fires AGAIN on 'item' at slot_store
                              // But S3 rc_drop_reassign fires on OLD current first
                              // Wait: is 'current' in ire_fullrc_drop? Only if
                              // EVERY store is ire_owned. 'items[0]' is borrowed,
                              // so the slot is NOT in S3's set.
    return current
// Without S3 on this slot: every conditional re-store does rc_inc(item)
// but the OLD current is never dec'd (no S3, no overwrite-drop).
// Over 1000 iterations with pred always true, the first element gets
// rc_inc'd 1000 times, never dec'd until scope-exit (which dec's ONCE).
// Net: RC inflated by 999. The value leaks forever.

fn branch_leak(cond, data)
    let temp = dict_keys(data)    // fresh list, RC=1
    if cond
        let result = process(temp)
        // temp is dead after this block -> W8 drops temp
        // ire_dropped['temp'] = 1
        return result
    // On the else path, temp is still live (used below)
    let result2 = other(temp)
    return result2
    // S4 scope-exit: checks ire_dropped for 'temp' -> FOUND
    // (set by the 'if' branch's W8 drop) -> SKIPS drop
    // But on THIS path, W8 never dropped temp (it was live).
    // temp leaks.

fn make_adder(base)
    let offset = compute_offset(base)  // fresh list, RC=1
    let add = fn(x) -> offset[0] + x   // make_closure captures 'offset'
                                         // rc_inc(offset) at capture -> RC=2
    // SCOPE EXIT: rc_dec(offset) -> RC 2->1. Closure still holds it. SAFE.
    return add
// This case is safe. But consider:
fn make_pair(data)
    let a = data[0]       // borrowed -> rc_inc at store -> RC(elem)=2
    let b = data[1]       // borrowed -> rc_inc at store -> RC(elem)=2
    let f = fn(x) -> a    // capture 'a' -> rc_inc(a) -> RC=3
    // S4 scope-exit drops 'a' AND 'b' (both owned after rc_inc)
    // rc_dec(a): RC 3->2 (closure + data still hold it). SAFE.
    // rc_dec(b): RC 2->1 (data still holds it). SAFE.
    return f
// Also safe. The design handles this correctly.
// BUT: what if 'data' is also a local (not a parameter)?
fn make_pair2()
    let data = [10, 20, 30]  // fresh, RC=1
    let a = data[0]          // borrow -> rc_inc -> RC(10)=2
    let f = fn(x) -> a       // capture a -> rc_inc(a) -> RC(10)=3
    // S4 drops: data (RC 1->0 -> nova_rc_free -> dec elements)
    //   element 10: RC 3->2 (slot 'a' + closure)
    //   element 20: RC 2->1 (slot 'a' has 20? No, slot b not here)
    //   Actually element 10 only: RC = 3 (data-list[0], slot 'a', closure)
    //   data freed: element 10 dec'd to 2. Still alive.
    // S4 drops: 'a' -> RC(10) 2->1. Closure still holds it. SAFE.
    // S4 drops order matters! If 'a' dropped BEFORE 'data':
    //   a: RC(10) 3->2. data: RC 1->0 -> free -> dec 10 to 1. SAFE.
    return f

fn iterate_unknown(obj)
    // obj could be a list OR a dict at runtime
    for item in obj
        process(item)
    // for_iter_init(obj): if dict -> dict_keys (fresh, RC=1, owned)
    //                     if list -> returns obj itself (borrowed, no RC bump)
    // Design Section 3.7 says: 'check if source is known list -> mark borrow;
    // if dict or unknown -> mark owned'
    // But 'unknown' is WRONG for the list case! If obj is actually a list
    // at runtime, marking owned means S4 will rc_dec the iterator at scope
    // exit. But the iterator IS obj (same pointer). rc_dec(obj) drops from
    // RC=1 (param borrowed) to 0 -> freed. Caller's reference is now dangling.

// The self-hosting compiler (nova_compiler.nova) has ~16000 lines,
// hundreds of functions, each with 5-20 local slots. A compilation
// of a 1000-line program likely executes millions of slot_stores.
// At 25ns per nova_rc_inc (dominated by nova_mem_find_tag pointer
// validation: alignment check, header read, magic compare, heap_base
// range check, strpool check, IsBadReadPtr on Windows), that's:
//   10M slot_stores * 25ns = 250ms overhead PER COMPILATION.
// The compiler currently compiles in ~2-3 seconds. This is a
// 8-12% regression on the compiler's own compilation time.
// Section 10.1 estimates '75-125ns per function call' which is
// optimistic -- it ignores that slot_stores happen INSIDE loops,
// not just once per function. A while-loop with 3 slot_stores
// iterating 1000 times = 3000 rc_inc calls = 75 microseconds
// for ONE loop. The compiler has hundreds of such loops.

fn mixed_drop(cond)
    let data = [[1,2], [3,4]]   // outer list RC=1, inner lists RC=2 each
    if cond
        let x = len(data)
        return x
        // W8: data is dead after len() call -> W8 drops data via
        // list_free_local: free(data->data), free(data). NO dec of
        // inner lists [1,2] and [3,4]. Their RC stays at 2 (from
        // list_append rc_inc). They leak.
    return data[0]
    // S4: data is in scope_drop. rc_dec(data) -> RC 1->0 ->
    // nova_rc_free -> dec inner lists from 2 to 1 each.
    // Still leaks! Because the initial list_append set RC=2 but
    // data was the only external owner.
// Actually the inner lists have RC=1 each (the outer list is their
// sole container, list_append did rc_inc bringing them to 2? No:
// make_list [1,2] creates inner list with RC=1. The outer make_list
// [[1,2],[3,4]] calls list_append(outer, inner) which rc_inc's inner.
// So inner RC=2. W8's list_free_local skips dec -> inner leaks at RC=2.
// On S4 path: nova_rc_free dec's inner from 2 to 1. Still leaked.

fn transform(data)
    let keys = dict_keys(data)  // fresh list
    let sorted = sort(keys)     // sort() returns a new list (or same?)
    let first = sorted[0]       // index_get -> borrowed
    let result = process(first) // call result -> owned
    return result
// ire_load_origin[result_reg] = ?? depends on whether 'result' was
// loaded from slot 'result' before return. If the return directly
// uses the call's dest register (no intermediate slot_load), then
// ire_load_origin is NOT set for the return register.
// In that case, returned_slot = '' and NO slot is excluded from drops.
// S4 drops ALL local slots including 'result'.
// But result IS the returned value! Double-free: caller and S4.

fn build_struct(data)
    let name = data['name']    // index_get -> borrowed
    // slot_store of 'name': rc_inc(name) -> RC=2 (dict + slot)
    let s = Foo{name: name}    // make_struct: name loaded from slot
    // Design Section 3.3: rc_inc(name) for non-owned field -> RC=3
    // But name already has RC=2 from the slot_store rc_inc.
    // Now: dict holds ref (RC contrib 1), slot holds ref (RC contrib 1),
    //       struct holds ref (RC contrib 1). Total = 3. Correct!
    // S4 scope-exit: rc_dec(name slot) -> RC 3->2. rc_dec(s) -> free ->
    // struct dec children -> rc_dec(name) -> RC 2->1. dict still holds.
    // This IS correct. The double rc_inc (slot + struct) matches
    // double rc_dec (scope-exit slot + struct free).
    return s
// Wait: returned_slot = 's'. So 's' is excluded from scope-exit.
// rc_dec(name slot) -> RC 3->2. 's' not dropped. Caller drops 's'
// eventually -> struct free -> rc_dec(name) -> RC 2->1. Still in dict.
// When does dict's ref get cleaned up? When dict is freed (by caller
// or caller's scope). OK, correct.
// BUT if the field value is an IMMEDIATE (int/float) that happens to
// pass the rc_is_managed check (a large int that looks like a pointer),
// rc_inc and rc_dec are harmless (find_tag returns 0). OK.

// Green task spawned, runs on carrier 0, allocates locals.
// Task parks (e.g., channel recv). Scheduler migrates it to carrier 1.
// Task resumes on carrier 1. Function returns -> scope-exit drops fire.
// nova_rc_dec calls nova_rc_is_managed which checks nova_heap_base.
// If each carrier has its own heap region (arena or slab), the pointer
// validation on carrier 1 may not recognize objects allocated on
// carrier 0's heap.
// The design does not address cross-carrier pointer validation.
// In practice, NOVA uses a global malloc (not per-carrier heaps),
// so nova_heap_base is global and find_tag works. But the design
// should state this assumption explicitly.

fn sender(ch, data)
    let msg = data[0]        // borrowed -> rc_inc at store -> RC(elem)=2
    channel_send(ch, msg)    // deep_copy(msg) -> fresh copy sent
    // msg slot still holds original ref with RC=2
    // S4 scope-exit: rc_dec(msg) -> RC 2->1. data still holds it. SAFE.
    // No leak here. The deep_copy is independent.
// This is actually fine. The rc_inc/dec pair on msg is balanced.

